$cats['Optical Illusions']['Optical Illusions Portals Double Exposure and Body Alignment'] = @('The Doorway to the Ocean','The Staircase to the Sky','The Wolf and the Wilderness','The Mountain Inside the Silhouette','The Butterfly Portal','The Arm as a Landscape','The Turning Wrist Spiral','The Knee Portal','The Elbow Infinity','The Full-Reality Illusion')
$cats['Material Illusions'] = [ordered]@{}
$test['Material Illusions'] = @('The Embroidered Butterfly','The Liquid Chrome Rose')
$cats['Material Illusions']['Material Illusions Embroidery and Thread'] = @('The Embroidered Butterfly','The Stitched Rose','The Threadwork Wolf','The Embroidered Skull','The Knitted Serpent','The Woven Peacock','The Cross-Stitched Heart','The Patchwork Tiger','The Lace Butterfly','The Golden Thread Phoenix')
$cats['Material Illusions']['Material Illusions Liquid Metal and Chrome'] = @('The Liquid Chrome Rose','The Melting Silver Skull','The Chrome Butterfly','The Liquid Gold Serpent','The Mercury Heart','The Chrome Panther','The Melted Metal Clock','The Liquid Chrome Dragon','The Crumpled Aluminum Butterfly','The Copper Tree')
$cats['Material Illusions']['Material Illusions Glass and Crystal'] = @('The Broken Glass Heart','The Crystal Rose','The Stained-Glass Raven','The Shattered Butterfly','The Glass Skull','The Diamond Serpent','The Frozen Glass Flower','The Glass Aquarium','The Prism Wolf','The Shattered Mirror Portrait')
$cats['Material Illusions']['Material Illusions Stone and Marble'] = @('The Marble Rose','The Cracked Obsidian Skull','The Stone Wolf','The Jade Dragon','The Marble Butterfly','The Crumbling Statue','The Amethyst Raven','The Sandstone Serpent','The Granite Heart','The Fossilized Butterfly')
$cats['Material Illusions']['Material Illusions Wood and Natural Materials'] = @('The Carved Wooden Wolf','The Wooden Rose','The Driftwood Seahorse','The Burning Wood Phoenix','The Bamboo Dragon','The Bark Butterfly','The Petrified Tree','The Wooden Mechanical Heart','The Corkwork Owl','The Carved Ivory Illusion')
$cats['Material Illusions']['Material Illusions Denim Leather and Fabric'] = @('The Denim Butterfly','The Leather Rose','The Zippered Heart','The Patchwork Dragon','The Velvet Raven','The Silk Serpent','The Burlap Skull','The Quilted Panther','The Torn Canvas Portrait','The Woven Feather Phoenix')
$cats['Material Illusions']['Material Illusions Jewelry and Precious Gems'] = @('The Diamond Panther','The Sapphire Butterfly','The Emerald Serpent','The Ruby Heart','The Pearl Octopus','The Opal Phoenix','The Gold Filigree Skull','The Crystal Eye','The Jeweled Scorpion','The Diamond Web')
$cats['Material Illusions']['Material Illusions Paper Origami and Print'] = @('The Origami Dragon','The Paper Butterfly','The Torn-Paper Rose','The Folded Crane','The Paper Skull','The Pop-Up Forest','The Newspaper Wolf','The Paper Ribbon Serpent','The Cut-Paper Portrait','The Paper Explosion')
$cats['Material Illusions']['Material Illusions Ceramic Porcelain and Enamel'] = @('The Porcelain Rose','The Cracked Ceramic Skull','The Mosaic Panther','The Enamel Butterfly','The Kintsugi Heart','The Delft Dragon','The Glazed Serpent','The Porcelain Doll Portrait','The Mosaic Galaxy','The Broken Teacup Garden')
$cats['Material Illusions']['Material Illusions Mixed Materials and Unexpected Textures'] = @('The Rusted Iron Rose','The Concrete Angel','The Wax Melting Portrait','The Carbon-Fiber Panther','The Inflatable Butterfly','The Crumpled Foil Skull','The Braided Rope Serpent','The Crystal-and-Metal Heart','The Melted Wax Butterfly','The Impossible Material Phoenix')
$mine = @(); foreach ($c in $cats.Keys) { $mine += @($cats[$c].Keys) }
$taken = @{}; $tt.specific.PSObject.Properties | ? { $mine -notcontains $_.Name } | % { $_.Value | ? { $_ } | % { $taken[(& $slug $_)] = 1 } }
$firstRun = -not (@($cats.Keys) | ? { $tt.subjects.PSObject.Properties[$_] })
if ($firstRun) {
  $fl = (npx wrangler kv key list --namespace-id $ns --prefix "face:v1:" --remote 2>$null | Out-String)
  $nf = 0; foreach ($m in [regex]::Matches($fl, '"name":\s*"face:v1:([^"]+)"')) { $taken[$m.Groups[1].Value] = 1; $nf++ }
  "  " + $nf + " drawn designs checked so no new name overwrites one"
  if ($nf -lt 1000) { "  STOP - the list of drawn designs came back short, nothing written - run the block again"; return }
} else { "  these categories are already in the catalog from the first run - names kept as they are" }
$final = @{}
foreach ($c in $cats.Keys) {
  $kinds = @($cats[$c].Keys)
  $had = @($tt.subjects.$c | ? { $_ }); "  " + $c + " already has " + $had.Count + " sets - the new ones are ADDED, nothing removed"
  $newKinds = @($kinds | ? { $had -notcontains $_ })
  if ($newKinds.Count -lt $kinds.Count) { "  " + ($kinds.Count - $newKinds.Count) + " of these sets are already in the catalogue from the first run - kept, not added twice" }
  if ($tt.subjects.PSObject.Properties[$c]) { $tt.subjects.$c = @($had + $newKinds) } else { $tt.subjects | Add-Member -NotePropertyName $c -NotePropertyValue $kinds }
  foreach ($k in $kinds) {
    $names = @($cats[$c][$k] | % { $o = $_; if ($taken.ContainsKey((& $slug $o))) { $nn = $o + " in " + $c + " Style"; "  RENAMED: " + $nn | Out-Host } else { $nn = $o }; $final[$o] = $nn; $nn })
    if ($tt.specific.PSObject.Properties[$k]) { $tt.specific.$k = $names } else { $tt.specific | Add-Member -NotePropertyName $k -NotePropertyValue $names }
  }
}
$json = $tt | ConvertTo-Json -Depth 20 -Compress
$check = $json | ConvertFrom-Json
$afterCats = @($check.subjects.PSObject.Properties).Count
if ($clash -or $afterCats -lt $beforeCats -or $json.Length -lt ($got.raw.Length * 0.9)) { "  SAFETY STOP - the new catalog looks smaller than the old one, nothing written" } else {
$tmp = Join-Path $env:TEMP "card-tree-new.json"
[System.IO.File]::WriteAllText($tmp, $json, (New-Object System.Text.UTF8Encoding $false))
npx wrangler kv key put --namespace-id $ns "card:tree" --path $tmp --remote 2>$null | Out-Null
"  catalog written in ONE save: " + $beforeCats + " categories before, " + $afterCats + " after"
"  saving the split-card settings and the tattoo descriptions..."
$n = 0
foreach ($c in $cats.Keys) { foreach ($k in $cats[$c].Keys) {
  $ks = & $slug $k
  RUN ("SETKV render:" + $ks + " The tattoo in both panels is identical.") | Out-Null
  RUN ("SETKV shape:" + $ks + " 3:2") | Out-Null
  RUN ("SETKV split:" + $ks + " yes") | Out-Null
  foreach ($o in $cats[$c][$k]) { RUN ("SETKV build:" + (& $slug $final[$o]) + " " + $b[$o]) | Out-Null; $n++ }
} }
"  " + $n + " descriptions saved - waiting 70 seconds so every server sees the new catalog..."
Start-Sleep -Seconds 70
$got2 = Read-Tree
$short = 0
foreach ($c in $cats.Keys) { foreach ($k in $cats[$c].Keys) { $h = @($got2.tree.specific.$k | ? { $_ }).Count; if ($h -ne $cats[$c][$k].Count) { "  STILL SHORT: " + $k + " has " + $h; $short++ } } }
if ($short) { "== " + $short + " sets short - send me this output ==" } else {
if (-not $short) {
"== saved: Optical Illusions and Material Illusions - 200 designs =="
$old = ((RUN "GETKV config:source:redo:model" | Out-String) | ConvertFrom-Json).payload.reply
if (-not $old) { $old = "" }
$bf = Join-Path (Get-Location) "redo-model-before.txt"
# A SECOND RUN KEEPS THE FIRST RUN'S RECORD: by then the setting already says gpt-image-2, which is not what it was before.
if (Test-Path $bf) { $old = (Get-Content $bf -Raw).Trim(); "  (kept the model saved by the first run)" } else { [System.IO.File]::WriteAllText($bf, [string]$old) }
"  the REDO model was: " + $old + " - saved to redo-model-before.txt; drawing this set on gpt-image-2"
RUN "SETKV config:source:redo:model gpt-image-2" | Out-Null
"  waiting 70 seconds so every server sees the model setting..."
Start-Sleep -Seconds 70
"== THE FOUR TEST CARDS, THROUGH THE REAL BATCH ROAD (REDO) =="
foreach ($c in $cats.Keys) { foreach ($tn in $test[$c]) { "-- test card for " + $c + ": " + $final[$tn]; RUN ("REDO " + $final[$tn]) } }
}
}
}
}
